(* [comment removed for export] *)
Lemma dl_R : forall regs m (s sx : Z),
  (112 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= sx < 2 ^ 31)%Z ->
  rdn SEGS m (Z_to_bv 64 (s - 84)) 4 = Some (Z_to_le_bytes 4 sx) -> getr regs 2 = Z_to_bv 64 (s - 112) ->
  exists regs',
    msteps SEGS (mkst regs (0x8f638 : word) m rom) (mkst regs' (0x8f5e0 : word) m rom)
